"""Session 2 documents, generated from results/results.json: docs/03_results/REDESIGN_B_RESULTS.md and docs/03_results/REDESIGN_DECISION_TABLE.md (D8). Every number is read from a key.

    python -m crashguard.rd_docs_b
"""
from __future__ import annotations

import json
from pathlib import Path

R = {e["name"]: e["value"] for e in json.loads(Path("results/results.json").read_text(encoding="utf-8"))}


def g(k):
    return R[k]


def f3(k):
    return f"{g(k):.3f}"


def sg(k):
    return f"{g(k):+.3f}"


HDR = """<!-- header:start -->
| Field | Value |
|---|---|
| Status | current |
| Date | 2026-11-14 |
| Owner | Mritula S |
| Scope | {scope} |
| Evidence labels used | SIMULATED, ANALYTICAL, MEASURED_SOFTWARE, NOT_RUN |
| Abbreviations | ACK = acknowledgement frame; D1 to D4 = redesigns of the retry policy, overhear-and-defer, slotted access and two-stage frame; ESP32 = microcontroller; GS-CA = GPS-slotted critical alerts; OS-DR = overhear-and-suppress retries with deadlines; SF = spreading factor (LoRa); UA-SCT = uncertainty-aware SCT |
<!-- header:end -->
"""

FAM = ("D1a", "D1b", "D1c", "D1s", "D2a", "D2b", "D2c", "D3", "D4a", "D4b")


def verdict(k):
    if k == "D4b":
        return "NOT_RUN"
    if k in ("D3", "D4a"):
        return g(f"rd.fb.{k}.verdict")
    return "SUPPORTED" if (g(f"rd.fa.{k}.criterion_met") and g(f"rd.fb.holm_final.{k}") < 0.05) else "NOT SUPPORTED"


def results_doc() -> str:
    L = ["# Redesign results, session 2: D3, D4, firmware path, cross-simulator check and final Holm", "", HDR.format(scope="FRESH-B results (D3, H-D4a), firmware decision path, cross-simulator verdicts for D1 and the final Holm table of the family of ten (generated)."),
         "Generated by `python -m crashguard.rd_docs_b`. Preregistration: `docs/02_preregistration/PREREGISTRATION_V12.md` (addenda A and B, with the disclosures of section 10.6). Constants: `docs/03_results/ASSUMPTIONS.md`. Session 1 results: `REDESIGN_A_RESULTS.md`. Code checks: `CODE_VERIFICATION.md`.", "",
         "## 1. Final Holm table (one family of ten)", "", "| Id | Raw p | Final Holm p | Verdict |", "|---|---|---|---|"]
    for k in FAM:
        raw = 1.0 if k == "D4b" else (g(f"rd.fb.{k}.p_raw") if k in ("D3", "D4a") else g(f"rd.fa.{k}.p_raw"))
        L.append(f"| H-{k[:2]}{k[2:]} | {raw:.4g} | {g(f'rd.fb.holm_final.{k}'):.4g} | {verdict(k)} |")
    L += ["", "Supported: " + ", ".join(f"H-{k}" for k in FAM if verdict(k) == "SUPPORTED") + ". Not supported or not run: " + ", ".join(f"H-{k}" for k in FAM if verdict(k) != "SUPPORTED") + ". H-D1c and H-D2c are formula or bounded-model checks (p = 0 when met).", "",
          "## 2. D3 (gated slotted retries), FRESH-B, next to the original GS-CA failure", "",
          f"Original failure: GS-CA lost in all 16 burst cells of the old held-out grid; 0.54 of its failed Critical alerts failed through a collision or a deaf gateway (`DIAGNOSIS_GSCA.md`). D3 (V12 10.2) slots only the retries, with the burst size taken from overheard frames, on top of the frozen D1 + D2. Grid: {g('rd.fb.d3.cells'):.0f} burst cells drawn from the freeze hash, 300 hours per cell, run once.", "",
          "| Quantity | Value |", "|---|---|", f"| Critical delivered within 10 s, D1 + D2 (mean over cells) | {f3('rd.fb.policy.D1D2.burst_mean_crit10')} |", f"| same, D3 | {f3('rd.fb.policy.D3.burst_mean_crit10')} |",
          f"| D3 minus D1 + D2 (pooled, 95% interval; 5 points required) | {sg('rd.fb.d3.crit10_gain_pt')} [{sg('rd.fb.d3.crit10_gain_lo')}, {sg('rd.fb.d3.crit10_gain_hi')}] |", f"| cells with a gain of at least 5 points | {g('rd.fb.d3.cells_with_gain_ge_5pt'):.0f} of {g('rd.fb.d3.cells'):.0f} |",
          f"| smallest per-cell difference in delivery before the own deadline (no-harm; lower bound) | {sg('rd.fb.d3.noharm_min_cell_diff')} ({sg('rd.fb.d3.noharm_min_lb95')}) |", f"| runs above the duty limit | {g('rd.fb.d3.duty_violations'):.0f} |", "",
          f"**D3 is a negative result** (kill rule of V12 10.2: the 5-point gain is not met; the no-harm part holds). The gain is real in sign (interval above zero) and about 80 times smaller than required. **Mechanism seen on the DEV grid (not on FRESH-B):** in a DEV burst hour the slots were used {g('rd.fbm.d3.slotted_retries_per_burst_hour'):.1f} times in total for {g('rd.fbm.d3.burst_critical_alerts_per_hour'):.0f} burst alerts with up to 12 retries each, because a vehicle rarely decodes two other vehicles in this channel model (vehicle-to-vehicle links are mostly out of range), so a burst-size estimate without an oracle is rarely available. GS-CA and the Tamang-style baseline both used a burst size given by an oracle. This reading is inferred from counts, not isolated by an ablation. Design deviations that may matter are in V12 10.6 (the gate counts other vehicles; slots apply to the flash of a round; the 5 s epoch cap does not hold at SF12).", "",
          "## 3. D4 (24-byte provisional frame), H-D4a, next to the original R2 and R3 results", "",
          "Original: R2 met the 5-point threshold in 10 of 16 cells but its sign test had p = 0.23 (power 0.22); R3's extra airtime was 38% against a 40% bound. The task text assumed R3's provisional frame was 97 bytes; in this repository it is a 14-byte flash (V12 10.1), so a 24-byte frame is longer, not shorter. H-D4a is the extra airtime of the two-stage scheme over the single-stage alert on the stored test events at the 1% target, 48 cells (6 spreading factors x 8 loss levels drawn after the freeze); criterion: upper 95% bound below 0.25 in every cell.", "",
          "| Provisional frame | Smallest extra airtime over the 48 cells | Largest | Cells with upper bound below 0.25 |", "|---|---|---|---|"]
    for name, lab in (("r3_flash14", "14-byte flash (R3 as registered)"), ("d4_prov24", "24-byte frame, 8-byte tag (D4)"), ("prov97", "97-byte frame (task wording of R3)")):
        L.append(f"| {lab} | {f3(f'rd.fb.d4.{name}.extra_airtime_min')} | {f3(f'rd.fb.d4.{name}.extra_airtime_max')} | {g(f'rd.fb.d4.{name}.cells_ub95_below_025'):.0f} of 48 |")
    L += ["", "**D4 is a negative result.** H-D4a fails in every cell, and the 24-byte frame costs more airtime than R3's own flash, as the arithmetic of V12 10.1 said. H-D4b (arrival time and burst delivery) was not run: it needs a two-stage alert with per-alert frame lengths in the simulator, which does not exist, and the kill rule ends D4 when H-D4a fails. NOT_RUN; it enters the family at p = 1. The lesson for the paper is about R3's premise: its provisional frame was already short.", "",
          "## 4. Firmware decision path (D6), host build", "",
          f"C decision path (`firmware_rd/`): time on air, SHA-256 and HMAC, the 97-byte alert and its tag, freshness, the D1 table lookup and Beta counters, Ed25519 verification of the cluster ACK (TweetNaCl, public domain), the D2 decision and defer rule, and the D3 slot rule. Differential test against the Python reference used by the simulator: {g('rd.d6.diff.traces'):.0f} random vehicle histories, {g('rd.d6.diff.ops'):.0f} compared operations (numbers bit for bit, frames and tags byte for byte), **{g('rd.d6.diff.mismatched_ops'):.0f} mismatches**. Replay of {g('rd.d6.replay.records'):.0f} decisions recorded inside real simulator runs (D1 lookups, defers, D3 slots, D2 decisions): **{g('rd.d6.replay.mismatches'):.0f} mismatches**. Host-build object sizes (x86-64, -Os, not the ESP32): firmware logic {g('rd.d6.size.host.cg_rd_text_bytes'):.0f} bytes of code, whole TweetNaCl {g('rd.d6.size.host.tweetnacl_text_bytes'):.0f} bytes; D1 table {g('rd.d6.size.d1_table_bytes_per_sf'):.0f} bytes per base spreading factor. **ESP32 flash and RAM, and the emulator run: NOT_RUN** (no Xtensa or RISC-V toolchain, no Espressif QEMU, no ESP-IDF here). The statement allowed in the paper: \"the firmware decision path was executed on simulated hardware-format inputs in a host build; an ESP32 emulator and a physical device were not used; no measurement on physical hardware is reported.\" The word \"simulated hardware-format inputs\" refers to the recorded simulator decisions and random traces; the hardware-format logs of `data/simulated_hardware` were not replayed through the C path (NOT_RUN). The trigger and severity code are the earlier exports (`firmware_export/`) and were not re-run in D6. Double precision is used so that results match Python bit for bit; an ESP32 port needs float or fixed point (NOT_RUN).", "",
          "## 5. Cross-simulator check for D1 (X1.3)", "", "Full tables and the list of differences: `XSIM_VERDICTS.md`. Summary on scenario S-X (32 SF9 cells of FRESH-A, 100 hours, ns-3 lorawan module and the custom simulator, frozen D1):", "",
          "| Hypothesis | Custom simulator | ns-3 | Same |", "|---|---|---|---|"]
    for k in ("D1a", "D1b", "D1c", "D1s"):
        a, b = g(f"rd.x13.custom.{k}.criterion_met"), g(f"rd.x13.ns3.{k}.criterion_met")
        L.append(f"| H-{k} | {'met' if a else 'not met'} | {'met' if b else 'not met'} | {'yes' if g(f'rd.x13.agree.{k}') else 'no'} |")
    L += ["", f"D1 minus the severity table at loss of 40% or more: custom {sg('rd.x13.custom.d1b.pt')} [{sg('rd.x13.custom.d1b.lo')}, {sg('rd.x13.custom.d1b.hi')}], ns-3 {sg('rd.x13.ns3.d1b.pt')} [{sg('rd.x13.ns3.d1b.lo')}, {sg('rd.x13.ns3.d1b.hi')}]. **D1's gain over the severity table is simulator-dependent**: it holds in the custom simulator and does not reach the 5-point bar or the no-harm bar in ns-3. It cannot be in the abstract, and D1 does not enter the main paper (V12 section 8 and D8). The calibration criterion of X1.2 was not met (one cell 5.4 points out), so even the agreement on H-D1c is stated under that condition. Against the best baseline of each cell (H-D1s) D1 is not supported in either simulator on S-X (on FRESH-A it was supported; the baselines there were chosen per cell on the same data). Possible reasons not isolated: the custom policies use a flash frame whose reception counts as delivery and ns-3's do not; different ACK length, timing and collision models.", "",
          "## 5b. Added after the second Session 2 prompt (ADDED-AFTER-SESSION-1)", "",
          "Nessa-style baseline, calibration under two sensitivity settings and the ns-3 run with the new baseline: `XSIM_VERDICTS.md`, `XSIM_CALIBRATION.md`, `REDESIGN_DECISION_TABLE.md`; keys `rd.fc.*`, `rd.x1.b.*`, `rd.x13.*`. None of this is in the Holm family and none changes a verdict above.", "",
          "## 6. Not done in session 2 (NOT_RUN, with reasons)", "",
          "- D4b (needs a feature the simulator lacks; moot after the failed H-D4a); ESP32 size and emulator (no toolchain); hardware-format log replay through the C path; ADR-on baseline in ns-3 (no data for ADR in a one-hour run); X1.4 comparison with the three published simulator papers (none opened); implementation of an adaptive scheme from the five closest papers as an extra baseline (none could be implemented from the text read: `CLOSEST_PRIOR_WORK.md`); the bench run of the two-stage alert (the author's: `docs/08_hardware/R3_BENCH_PROTOCOL.md`; `rd.x4.hw_row` NOT_RUN).",
          "- Searches: OpenAlex returned HTTP 503; IEEE Xplore, Scopus, Google Scholar and TRID were not run (`NOVELTY_SCAN.md`)."]
    return "\n".join(L) + "\n"


def decision_doc() -> str:
    row = lambda *c: "| " + " | ".join(c) + " |"  # noqa: E731
    d1b = f"{sg('rd.fa.d1b.pt')} [{sg('rd.fa.d1b.lo')}, {sg('rd.fa.d1b.hi')}]"
    xs = f"custom {sg('rd.x13.custom.d1b.pt')}, ns-3 {sg('rd.x13.ns3.d1b.pt')}"
    L = ["# Redesign decision table (D8)", "", HDR.format(scope="One row per hypothesis of the redesign round: original result, diagnosis, redesign, fresh held-out result, verdict, nearest prior work, allowed wording and placement (generated)."),
         "Rule (D8): a redesign enters the main paper only if it is supported in the custom simulator AND agrees in the established simulator; supported ones are described as \"v2 designed from a diagnosis of v1 failure, tested once on a fresh held-out grid\". Failed ones go to the negatives register. Final Holm p-values: `REDESIGN_B_RESULTS.md`. Every table caption points to `ASSUMPTIONS.md`.", "",
         "| Id | Original result | Diagnosis | Redesign | Fresh held-out result (95% interval) | Verdict | Nearest prior work | Allowed wording | Placement |", "|---|---|---|---|---|---|---|---|---|",
         row("H-D1a", "UA-SCT lost to the severity table in some cells (`DIAGNOSIS_UASCT.md`)", "static table; 5 s spacing leaves too few tries at high loss; gain only from lowered thresholds", "D1 loss-adaptive deadline table", f"FRESH-A: smallest per-cell gain {sg('rd.fa.d1a.min_cell_diff')}; ns-3 on S-X: smallest {sg('rd.x13.ns3.d1a.min_cell_diff')}, {g('rd.x13.ns3.d1a.cells_failing'):.0f} cells fail", f"{verdict('D1a')} in the custom simulator; **differs in ns-3 (simulator-dependent)**", "retry limits and timeouts in LoRaWAN and Khan et al.; the 2020 mines paper not opened", "In the custom simulator D1 did not lose to the severity table in any of 64 cells; in ns-3 it did in some cells.", "supplement"),
         row("H-D1b", "same; quick retries won at high loss", "same", "D1", f"FRESH-A {d1b}; S-X: {xs}", f"{verdict('D1b')} in the custom simulator; **not met in ns-3**", "as above", "D1 raised delivery by about 16 points at loss of 40% or more in the custom simulator; the gain was about 2 points in ns-3 and is simulator-dependent.", "supplement; not in the abstract"),
         row("H-D1c", "duty limit", "airtime within budget", "D1 budget in the table", "0 runs above the limit in both simulators", verdict("D1c"), "LoRaWAN duty rules (regulatory value not verified)", "D1 stayed inside the duty limit in every simulated run.", "supplement"),
         row("H-D1s", "(strict baseline)", "six baselines per cell; Nessa-style added after Session 1 (ADDED-AFTER-SESSION-1)", "D1", f"FRESH-A six baselines: smallest {sg('rd.fa.d1s.min_cell_diff')}, mean {sg('rd.fa.d1s.mean_diff')}; **with the Nessa-style baseline added (ADDED-AFTER-SESSION-1, not in the Holm family): smallest {sg('rd.fc.d1s7.min_cell_diff')}, mean {sg('rd.fc.d1s7.mean_diff')}, {g('rd.fc.d1s7.cells_failing'):.0f} cells below the bound**; S-X not met in both simulators", f"{verdict('D1s')} on FRESH-A with six baselines; **NOT SUPPORTED with seven (ADDED-AFTER-SESSION-1)**; not met on S-X", "Nessa et al. CNS 2020 (secondary description), Tamang-style slots, quick retries", "Against the best baseline of each cell D1 is not shown to be better: the gain over the best of seven is about 2 points on average and negative in some cells. D1 is better than the severity table, and than quick retries by about 3.6 points, but not reliably better than the best baseline per cell.", "supplement"),
         row("H-D2a", "OS-DR lost in 8 of 32 cells", "0.88 of suppressed alerts had never reached the base", "D2 gateway-signed cluster ACK, stop only if listed, defer otherwise", f"smallest per-cell change {sg('rd.fa.d2a.min_cell_diff')}", verdict("D2a"), "aggregated or group ACKs for LoRaWAN exist (A2S2-LoRaWAN, DG-LoRa; abstract level)", "D2 did not lose delivery in any cell.", "supplement"),
         row("H-D2b", "same", "same", "D2", f"burst gain {sg('rd.fa.d2b.pt')} [{sg('rd.fa.d2b.lo')}, {sg('rd.fa.d2b.hi')}] against 5 points required", verdict("D2b"), "as above", "No claim of a burst gain. Negative result.", "negatives register"),
         row("H-D2c", "event ACK under a shared key can be forged by a key holder", "shared key", "gateway-signed listing", "bounded model: no vehicle-key holder stops another vehicle; stolen gateway key is outside the claim", verdict("D2c"), "none found in the sources checked (not a claim of absence)", "In a bounded model (2 vehicles, small bounds) a holder of only a vehicle key could not make another vehicle stop retrying.", "supplement"),
         row("H-D3", "GS-CA lost in all 16 burst cells", "0.54 of failures were collisions or a deaf gateway; fixed K put 2.7 times as many frames on the channel", "D3 slotted retries, burst size from overheard frames", f"gain {sg('rd.fb.d3.crit10_gain_pt')} [{sg('rd.fb.d3.crit10_gain_lo')}, {sg('rd.fb.d3.crit10_gain_hi')}] against 5 points required; no harm", verdict("D3"), "Tamang et al. MSWiM 2023 (abstract level); synchronous LoRa (arXiv 2012.07480)", "No claim. Slotting without an oracle rarely activates because vehicles rarely overhear each other in this channel model (inferred).", "negatives register"),
         row("H-D4a", "R3 extra airtime 38% against a 40% bound; R2 frame effect not significant (power 0.22)", "R3's provisional frame is already a 14-byte flash; a 24-byte frame is longer", "D4 24-byte provisional frame with 8-byte tag", f"extra airtime {f3('rd.fb.d4.d4_prov24.extra_airtime_min')} to {f3('rd.fb.d4.d4_prov24.extra_airtime_max')}; 0 of 48 cells below 0.25", verdict("D4a"), "US 9758120 (provisional crash alarm over cellular, patent)", "No claim. The short provisional frame did not lower the extra airtime of the two-stage alert.", "negatives register"),
         row("H-D4b", "as H-D4a", "as H-D4a", "D4", "not run", "NOT_RUN", "as above", "No claim.", "NOT_RUN list")]
    L += ["", "## D1 against the baselines (A1 and A2)", "",
          f"- **The severity table is a weak baseline here** (it waits 5 s before the initial Critical send and retries without spacing). **Most of D1's gain over it is also available from quick retries:** D1 minus quick retries is {sg('rd.fc.d1_minus_quick.pt')} [{sg('rd.fc.d1_minus_quick.lo')}, {sg('rd.fc.d1_minus_quick.hi')}] over the FRESH-A cells, against {sg('rd.fa.d1b.pt')} over the severity table at loss of 40% or more. The abstract and the claims use D1 against the best baseline per cell, not against the table.",
          f"- **Nessa-style baseline (ADDED-AFTER-SESSION-1; implemented from a secondary description, parameters k = {g('rd.fc.nessa.params_k'):g}, A = {g('rd.fc.nessa.params_A'):g} s chosen on the DEV grid):** D1 minus Nessa-style {sg('rd.fc.d1_minus_nessa.pt')} [{sg('rd.fc.d1_minus_nessa.lo')}, {sg('rd.fc.d1_minus_nessa.hi')}] pooled over the 64 FRESH-A cells; D1 is better by at least 2 points in {g('rd.fc.d1_minus_nessa.share_cells_ge_2pt'):.0%} of the cells ({g('rd.fc.d1_minus_nessa.share_cells_lb_gt_2pt'):.0%} with the lower bound above 2 points); range per cell {sg('rd.fc.d1_minus_nessa.min_cell')} to {sg('rd.fc.d1_minus_nessa.max_cell')}. By the reading rule fixed in V12 11.1 D1 is better than Nessa-style on average. Nessa-style is the best of the seven baselines in {g('rd.fc.d1s7.best_nessa_cells'):.0f} cells, and H-D1s with seven baselines is **not met** ({g('rd.fc.d1s7.cells_failing'):.0f} cells below the -2 point bound).",
          "- Reading: D1 is not claimed as an improvement over the best baseline per cell, and it is not claimed over prior work in general (the CNS 2020 paper was not opened).", "", "## Reading", "",
          "- **Main paper:** nothing from the redesign round passes the D8 rule. D1 is supported in the custom simulator but does not agree in ns-3 on H-D1a and H-D1b, so it goes to the supplement with the simulator-dependence stated.",
          "- **Negative results kept:** D2 (H-D2b), D3, D4 (`NEGATIVES_REGISTER.md`), next to the original failures they were meant to fix.",
          "- **Hardware:** none. The bench protocol for the two-stage alert is ready (`docs/08_hardware/R3_BENCH_PROTOCOL.md`); the row is NOT_RUN until the author supplies real logs.",
          "- Absence statements use the form \"no study found in the sources checked\" (web search; IEEE Xplore, OpenAlex (HTTP 503), Scopus, Google Scholar and TRID not run).",
          "", "## Disclosures carried into the paper (A7)", "",
          "- The fresh grids share the finite pool of real class pairs and early-exit decision times with development; freshness holds for arrivals, channel draws and geometry.",
          "- The bounded model of H-D2c is exhaustive for 2 vehicles at the preregistered bounds; for 3 vehicles the bounds were reduced (attacker actions at most 2, losses at most 1, one send per vehicle).",
          "- The test statistic is the more conservative of the event bootstrap and the hour-clustered bootstrap.",
          "- Three older tests had failed on numpy-2 attribute errors (`np.trapz`); a compatibility shim replaces the calls without changing any value and the three tests now pass.",
          "- The calibration of the custom simulator against ns-3 missed its own criterion (one cell at 5.4 points in setting (a)); both sensitivity settings are reported in `XSIM_CALIBRATION.md`.",
          "- The Nessa-style baseline was implemented from a secondary description and added after Session 1 (ADDED-AFTER-SESSION-1); it is outside the Holm family."]
    return "\n".join(L) + "\n"


CV_MARK = "<!-- cv-session2:start -->"


def cv_section(n_pass: int) -> str:
    kb = lambda k: g(f"rd.cv.mutation_b.{k}")  # noqa: E731
    return f"""{CV_MARK}
## 9. Session 2: D3, D4, the C firmware path, the ns-3 application and FRESH-B machinery

Tests: `tests/redesign/` now has {n_pass} passing tests (session 1: 39). New files: `test_rd_d3.py` (hand-computed slot cases, property tests with hypothesis for the slot bounds, deadline and no-stop rule, simulator invariants, D3-off equals D1 + D2 bit for bit, simulator decisions equal the pure function), `test_rd_firmware_diff.py` (SHA-256 and HMAC known answers including RFC 4231 case 3, airtime and bin hand cases, non-canonical Ed25519 signature rejected by both sides, a 1,000-trace differential run, replay of simulator decisions), `test_rd_d4_fresh_b.py` (hand-computed extra airtime, **known-answer reproduction of the stored R3 extra airtime 0.38038 and 0.33617**, monotonicity in the provisional frame length, a smoke run of the whole FRESH-B analysis on a tiny grid before the single real run), `test_rd_regression_a.py` (**D1 and D1 + D2 under the current simulator reproduce the stored FRESH-A per-event delays bit for bit**), `test_rd_bench.py` (bench-log parser on a synthetic fixture, DUMMY DATA).

**CV4 differential test.** {g('rd.d6.diff.traces'):.0f} random vehicle histories ({g('rd.d6.diff.ops'):.0f} operations: Beta updates, D1 lookups, bins, defers, D3 slots, the D2 decision, alert frames and tags, tampered and extended tags, freshness sequences, cluster ACKs of 16 kinds including valid, tampered, replayed, stale, truncated, malformed but signed, wrong key and non-canonical signature) compared between the C path and the Python reference: **{g('rd.d6.diff.mismatched_ops'):.0f} mismatches**; {g('rd.d6.replay.records'):.0f} decisions recorded inside real simulator runs replayed through the C path: **{g('rd.d6.replay.mismatches'):.0f} mismatches**. Weak spots found by the review and not fixed: some comparisons are weak by construction (the D2 decision is compared with a copy of the branch condition; the cluster check of the simulator is an abstraction of the signature check, so cryptography is tested by unit tests and the differential run, not inside the simulator); D3 slot times in the random ops use t_min below 40 s (real times come from the replay only); the replay contains few D3 slot decisions (the D3 slots are rarely used, which is also the finding of H-D3).

**CV5 mutation testing** (`scripts/rd_mutation_b.py`, 22 mutants of `rd_d3.py`, 5 of its simulator integration, 26 of the C path; mutmut does not run on Windows): {kb('killed'):.0f} of {kb('mutants'):.0f} killed ({kb('killed_share'):.0%}); survivors: {kb('survivors')}. A mutant counts as killed only when it compiles and a test or a differential comparison fails (an earlier run of this script counted compile errors caused by a space in the temporary path as kills; that was found and corrected, and the table was re-made). Survivors read one by one (`results/tables/rd_mutation_b.csv`): W04 (a vehicle "hears itself": `node_link` returns false for the same node) and C26 (a no-op) are equivalent mutants; D18 (the 5 ms clock offset ignored when choosing the epoch) is equivalent except at an epoch boundary that no test hits; **C12 is a real weakness**: without the "no time left" check the C lookup reads outside the table for a non-positive time left, and the random traces happened to return the same "no action" answer; a test with a non-positive time left that checks the index is in range is not written.

**CV6 independent review** (fresh-context subagent, told not to read results; it read V12 sections 1, 3, 4, 6, 9, 10, the D3, D4, FRESH-B and firmware code and the tests). 18 findings, no use of held-out data, no way to run FRESH-B twice. Fixed before the freeze: H-D4b wording in the analysis, an analyse-only entry point and a pre-flight check for the single run, the freeze fallback when no D3 iteration meets the DEV floor and a longer freeze hash list, C hardening (exact tag frame length, ring bounds, harness token handling, HMAC over-length path), seeded Ed25519 keys in the generator, a stale-binary risk in a test. Disclosed and not changed because D3 DEV had already run (V12 10.6): the D3 gate counts other vehicles; the overhearing model; the slot is applied to the flash of a round; the 5 s epoch cap does not hold at SF12; S_MAX; `alt` outside the budget plan; `world_sim.py` and `rd_eval.py` changed after the FRESH-A freeze (equivalence tested bit for bit). After the freeze nothing was changed.

**CV7 known answers.** The R3 extra airtime (above) and the FRESH-A D1 and D1 + D2 delays are reproduced with the current code. The three session 1 known answers (UA-SCT cell, OS-DR cell, R3) are in `test_rd_sim.py` and pass.

**Not done:** a differential test of the ns-3 application against the Python simulator (they are different simulators by design; the D1 lookup inside ns-3 is the same C code, tested above); mutation testing of `rd_x13.py`; ESP32 or emulator execution of the C path.
"""


def append_cv(n_pass: int) -> None:
    p = Path("docs/03_results/CODE_VERIFICATION.md")
    s = p.read_text(encoding="utf-8")
    if CV_MARK in s:
        s = s[: s.index(CV_MARK)].rstrip("\n") + "\n\n"
    p.write_text(s.rstrip("\n") + "\n\n" + cv_section(n_pass), encoding="utf-8")


def main() -> None:
    Path("docs/03_results/REDESIGN_B_RESULTS.md").write_text(results_doc(), encoding="utf-8")
    Path("docs/03_results/REDESIGN_DECISION_TABLE.md").write_text(decision_doc(), encoding="utf-8")
    import sys

    if len(sys.argv) > 1:
        append_cv(int(sys.argv[1]))
    print("written")


if __name__ == "__main__":
    main()


